INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f4e9174e-8067-45cb-97bd-56e0628f5b55', 'c3c3c3c3-3030-4000-8000-000000000003', 24, 'Dia 24 — Contentamento', 'Semana 4: Integrar', '{"pch": "Aprendi a estar contente em toda situa\u00e7\u00e3o\u2026 Contentamento n\u00e3o \u00e9 conformismo \u2014 \u00e9 liberdade.", "verse": "Fl 4,11", "lectio": "Leia Fl 4,10-13. O segredo de Paulo.", "practice": "Liste 10 coisas que j\u00e1 tem e que algu\u00e9m sonha em ter.", "question": "O que te falta para ser feliz? Ser\u00e1 que realmente falta?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;